llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "In patients with cirrhosis, metoclopramide had an absolute oral bioavailability of 79.0 ± 18.8% (range 49–103%), supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "In patients with alcoholic cirrhosis, tolfenamic acid had an absolute oral bioavailability of about 100% versus IV, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "In cystic fibrosis patients, free PABA showed an oral bioavailability of 90.1 ± 8.7%, providing additional high-bioavailability evidence with the highest assay-transfer score.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferred evidence supports F ≥ 20%; direct cirrhosis records show high absolute bioavailability, and additional high-F records reinforce the prediction.",
  "evidence_gaps": [
    "Cirrhosis-specific evidence is limited to two transferred molecules; other evidence is from healthy subjects or non-cirrhosis conditions.",
    "A low azosemide estimate (C69) was discounted because it relied on urinary excretion with non-matched IV/oral studies."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

